import{_ as t,o,c as s,a2 as r}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Persistence","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/persistence.md","filePath":"concepts/persistence.md","lastUpdated":1793739519000}'),a={name:"concepts/persistence.md"};function d(c,e,n,i,h,l){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h1><p>kernl keeps the user&#39;s choices in the browser they made them in, and nowhere else. There is no kernl server, no sync and no account to log in to. This page lists every key kernl writes, what each holds, and what is deliberately never written.</p><h2 id="where-values-go" tabindex="-1">Where values go <a class="header-anchor" href="#where-values-go" aria-label="Permalink to &quot;Where values go&quot;">​</a></h2><p><code>@kernl/core</code> never touches <code>localStorage</code> itself. It writes to <code>KernlHost.storage</code>, a <code>StorageLike</code> (<code>getItem</code>, <code>setItem</code>, <code>removeItem</code>) the host supplies. The shell app supplies <code>pickStorage()</code> from <code>apps/web/src/shell/host.ts</code>: <code>localStorage</code> when a probe write succeeds, otherwise a <code>Map</code> that lives as long as the page. In a private window that refuses storage, the shell still works and forgets everything on reload.</p><p>Inside the core, every key goes through <code>createNamespacedStore(storage, &#39;kernl&#39;)</code>, which prefixes each key with <code>kernl:</code> and stores JSON:</p><table tabindex="0"><thead><tr><th>Method</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>getJson(key, fallback)</code></td><td>Reads <code>kernl:&lt;key&gt;</code> and parses it. Returns <code>fallback</code> when the key is absent or the JSON is corrupt; it never throws, so a damaged value cannot stop the shell from booting.</td></tr><tr><td><code>setJson(key, value)</code></td><td>Serialises and writes <code>kernl:&lt;key&gt;</code>.</td></tr><tr><td><code>remove(key)</code></td><td>Removes <code>kernl:&lt;key&gt;</code>.</td></tr></tbody></table><p>The prefix keeps kernl&#39;s keys apart from kehto&#39;s and from the host app&#39;s in the same storage. Every key carries a <code>:v1</code> suffix so a future format can move to <code>:v2</code> without reading the old one wrongly.</p><h2 id="keys-the-core-writes" tabindex="-1">Keys the core writes <a class="header-anchor" href="#keys-the-core-writes" aria-label="Permalink to &quot;Keys the core writes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Written by</th><th>Holds</th></tr></thead><tbody><tr><td><code>kernl:accounts:v1</code></td><td><code>createKernlAccounts</code></td><td>applesauce&#39;s <code>AccountManager.toJSON(true)</code>: the serialised accounts, minus any that cannot be serialised. Rewritten whenever the account list changes.</td></tr><tr><td><code>kernl:active-account:v1</code></td><td><code>createKernlAccounts</code></td><td>The active account&#39;s id. Removed when no account is active.</td></tr><tr><td><code>kernl:grants:v1</code></td><td><code>createGrants</code></td><td>One record per verified applet build, keyed <code>&lt;dTag&gt;:&lt;hash&gt;</code>: <code>{ dTag, hash, domains, blocked }</code>. See <a href="./identity-and-grants">Identity and grants</a>.</td></tr><tr><td><code>kernl:relays:v1</code></td><td><code>createRelayTiers</code></td><td>The four relay tiers, each a list of URLs. See <a href="./relay-tiers">Relay tiers</a>.</td></tr><tr><td><code>kernl:messaging:v1</code></td><td><code>createDefaultMessaging</code></td><td><code>MessagingPreferences</code>: the <code>enabled</code> provider ids and the optional <code>defaultProvider</code>. See <a href="./messaging">Messaging</a>.</td></tr></tbody></table><p>On boot, <code>createKernlAccounts</code> restores the accounts and makes the stored id active if that account still exists. <code>createGrants</code> loads its records, and <code>createRelayTiers</code> and <code>createDefaultMessaging</code> start from the stored value when there is one.</p><h2 id="keys-the-shell-app-writes" tabindex="-1">Keys the shell app writes <a class="header-anchor" href="#keys-the-shell-app-writes" aria-label="Permalink to &quot;Keys the shell app writes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Written by</th><th>Holds</th></tr></thead><tbody><tr><td><code>kernl:recent:v1</code></td><td><code>recent.ts</code>, through the host storage</td><td>The recently opened applets: up to eight <code>{ address, title, publisher, openedAt }</code>, newest first. Opening an applet moves it to the front; the launcher can forget one.</td></tr><tr><td><code>kernl:layout:v1</code></td><td><code>window-store.svelte.ts</code>, to <code>localStorage</code> directly</td><td><code>floating</code> or <code>tiled</code>, as a plain string. A refused write is ignored and the layout applies to the current page only. See <a href="./layouts">Layouts</a>.</td></tr><tr><td><code>kernl:preview:grants:v1</code>, <code>kernl:preview:relays:v1</code>, <code>kernl:preview:messaging:v1</code></td><td>the offline preview (<code>?preview=1</code>)</td><td>The preview&#39;s own grants, tiers and messaging preferences, kept apart so that trying the preview never changes the live shell&#39;s state.</td></tr></tbody></table><p>The public website also remembers its colour scheme as <code>kernl-theme</code> (<code>light</code> or <code>dark</code>). That key belongs to the site pages, not to the shell.</p><h2 id="keys-kehto-writes" tabindex="-1">Keys kehto writes <a class="header-anchor" href="#keys-kehto-writes" aria-label="Permalink to &quot;Keys kehto writes&quot;">​</a></h2><p>kernl passes no persistence hooks of its own to <code>createShellBridge</code>, so kehto uses its defaults from <code>@kehto/shell</code>, which write to <code>localStorage</code> directly rather than to <code>host.storage</code>. In <code>@kehto/shell</code> 0.29.0 those are <code>napplet:acl</code> (the runtime ACL, which <code>kernl:grants:v1</code> mirrors per applet build), <code>napplet:manifest-cache</code>, <code>napplet-shell-secret</code>, <code>napplet-guid:&lt;windowId&gt;</code>, and the scoped keys behind the <code>storage</code> NAP domain, where an applet&#39;s own data lives. kernl does not read or migrate these keys; their format is kehto&#39;s.</p><h2 id="what-is-never-persisted" tabindex="-1">What is never persisted <a class="header-anchor" href="#what-is-never-persisted" aria-label="Permalink to &quot;What is never persisted&quot;">​</a></h2><ul><li><strong>Plaintext private keys.</strong> <code>KernlAccountManager.addAccount</code> refuses the account types whose serialised form carries a raw secret (<code>PLAINTEXT_KEY_ACCOUNT_TYPES</code>: <code>nsec</code> and <code>seed-words</code>) with <code>denied:plaintext-key-persistence</code>, and restore drops any such entry it finds in storage. The only stored form of a local key is applesauce&#39;s <code>PasswordAccount</code>, whose <code>ncryptsec</code> is NIP-49 encrypted with the user&#39;s password. The password itself is never stored.</li><li><strong>The preview account.</strong> &quot;Try the preview&quot; creates a throwaway key account in a plain <code>AccountManager</code> that is not connected to storage, so it disappears on reload.</li><li><strong>The guard profile.</strong> <code>GuardFacade.setProfile</code> changes the profile for the running shell only. Every boot starts <code>strict</code> (<a href="./../decisions#d-003">D-003</a>).</li><li><strong>Open windows.</strong> The window store persists only the layout. Applets are not reopened on reload; the recent list is how the user gets back to them.</li></ul><p>Some stored values are sensitive even though they are not the user&#39;s key. A browser-extension account stores only its public key, because the extension holds the secret. A remote-signer account stores what applesauce needs to reconnect: the remote signer&#39;s public key, its relays, the pairing secret when there is one, and the client key of the pairing session in hex. That client key is not the user&#39;s identity key, but anyone who reads it from this browser&#39;s storage can talk to the remote signer as this session until the user revokes the pairing in the signer.</p><h2 id="clearing-it" tabindex="-1">Clearing it <a class="header-anchor" href="#clearing-it" aria-label="Permalink to &quot;Clearing it&quot;">​</a></h2><p>Signing out clears the active account and keeps the account in the list, so it can be picked again. <strong>Forget</strong> on the sign-in screen removes a stored account. Removing everything kernl stored means clearing the site&#39;s storage in the browser. Nothing is held anywhere else, so there is nothing else to delete.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./identity-and-grants">Identity and grants</a></li><li><a href="./relay-tiers">Relay tiers</a></li><li><a href="./../alpha-status#what-does-not-work-yet">Alpha status</a></li></ul>',22)])])}const u=t(a,[["render",d]]);export{g as __pageData,u as default};
